// ru: Russian, the words of site/js/copy/en.js, en.later.js, en.facts.js and the Moments files (release 1.6.3, public translation issues).
// Fetched by copy/index.js only when the page speaks Russian (?lang=ru); hidden until a native reader has signed off (docs/TRANSLATING.md).
//
// STATUS: MACHINE-DRAFTED. Every string was drafted by a program from the English and has NOT been read by a native speaker.
// Until a second native speaker has read it and put their name in `review.by`, copy/lang.js keeps `reviewed: false`, so the page
// speaks Russian only to a visitor who asks for it (?lang=ru), and the language picker does not list it.
//
// CHOICES, so a reviewer can disagree with them:
//   * Register: «вы» (neutral, polite); buttons and titles are mostly imperative infinitives or nouns.
//   * Honesty words, one each: измерено (measured), рассчитано (worked out/computed/propagated), смоделировано (modelled), иллюстративно (illustrative), восстановлено (reconstructed), рисунок художника (artist's impression), образец (sample).
//   * Planets and moons use standard Russian (Юпитер, Ио, Титан, Энцелад, Харон, Луна, Солнце); human names are in Cyrillic (Гагарин, Армстронг, Королёв, Уайсмен).
//   * Spacecraft, telescopes, agencies and catalogues keep their Latin names (Voyager 2, Cassini, Hubble, Webb, NASA JPL); only МКС and Тяньгун are Cyrillic, since the app shows them so.
//   * Counted nouns avoid Russian agreement: «Остановок: {n}», «объектов: {n}»; short forms for units: мин, ч, дн., л. (years), св. лет, а. е.; a few spots (e.g. «{n} л. назад» for years ago) stay approximate.
//   * Number words (numberWords) are masculine nominative, with «ноль» for none; rightNow.storms is written «{n} — столько штормов кружит сейчас» because the code capitalises the word.
//   * Compass words are nominative so «Смотрите на {dir}» works; «в направлении» phrases use «направление — {az}» since no prepositional forms exist.
//   * RULES.plural: three forms (1 / 2-4 / 5+) with «one» and «few|many»; fractions take the genitive singular. Articles: none.
//   * Gagarin's and Korolev's quotes are given in Russian (said in Russian); Armstrong's stay English. «Косберг сработал!» and «Вижу Землю…» are back-translations from the English: check against the originals.
//   * Unsure: moon class «Естественный спутник» vs satellite «Спутник»; tab «Ночью» for Tonight; Look panel «Облик» with modes «Измерено» / «Кино»; articles, exoface.a/an and theWord are a zero-width space (an empty string would show the English).
//   * Planet-class strings that need case (e.g. {parent}, {world}, {name} after prepositions) are phrased with a colon or dash to avoid declining names from data.

export const META = {
  code: "ru",
  name: "Русский",
  english: "Russian",
  review: { status: 'machine-drafted', by: [], note: 'Needs a native reader and a second reader (docs/TRANSLATING.md, Review).' },
};

export const RULES = {
  decimal: ',',
  /** Russian has no indefinite article. */
  article() {
    return '';
  },
  /**
   * Three forms. `one` is the form after 1 ("минута"); `many` is "few|many", e.g. "минуты|минут".
   * Integers: 1, 21, 31... take `one`; 2-4 (but not 12-14) take few; the rest take many.
   * A fractional number ("1,5 часа") takes the genitive singular, which is the few form.
   */
  plural(n, one, many) {
    const [few, lots] = String(many).split('|');
    const few2 = few || one;
    const lots2 = lots || few2;
    const a = Math.abs(Number(n));
    if (!Number.isFinite(a)) return lots2;
    if (a !== Math.floor(a)) return few2;
    const m10 = a % 10;
    const m100 = a % 100;
    if (m10 === 1 && m100 !== 11) return one;
    if (m10 >= 2 && m10 <= 4 && (m100 < 12 || m100 > 14)) return few2;
    return lots2;
  },
};

