        "own": "Поверхность Титана так, как её увидела камера Cassini сквозь дымку в ближнем инфракрасном свете (938 нм), в оранжевом цвете дымки. Моря на севере затемнены по контурам, которые нарисовал радар Cassini, а вблизи, где в них отражается Солнце, они бликуют: где лежит блик, рассчитано; его размер и яркость иллюстративны.",
        "radar": "Полосы поверхности Титана так, как их увидел радар Cassini сквозь дымку в 2004–2015 годах: светлое — неровная поверхность или наклонённая к радару, тёмное — гладкая, а моря жидкого метана и этана чёрные. Серый цвет наш: у радара цвета нет. Радар увидел 61 % Титана; между полосами сквозь них проступает приглушённая оранжевая инфракрасная карта. USGS Astrogeology и NASA/JPL-Caltech, общественное достояние."
