  "r13Deep": {
    "card": {
      "dso-tarantula-nebula": "Свет у нашей линии зрения — фотография Webb; его газ — модель полости вокруг скопления R136 внутри оболочки светящегося газа, ограниченной молекулярными облаками, по Pellegrini, Baldwin и Ferland (2011). Астроном эту модель ещё не проверял.",
      "dso-m43": "Свет взят с фотографии ESO, форма восстановлена как меньшая впадина на том же тёмном облаке, что и туманность Ориона, освещённая звездой NU Orionis. Астроном эту модель ещё не проверял.",
      "dso-m51": "Построено по опубликованному наклону и структуре: двухрукавная спираль, видимая почти плашмя, её спутник NGC 5195 позади конца северного рукава и рукав, который до него тянется; глубины — модель. Астроном эту модель ещё не проверял.",
      "dso-m81": "Построено по опубликованному наклону и структуре: большое старое центральное утолщение и два туго закрученных рукава с пылью на внутренних краях. Астроном эту модель ещё не проверял.",
      "dso-m101": "Построено по опубликованному наклону и структуре: большой диск, видимый почти плашмя, много рукавов и гигантские области звездообразования там, где их помещает небо. Астроном эту модель ещё не проверял.",
      "dso-m104": "Построено по опубликованному наклону и структуре: огромное круглое центральное утолщение и тонкий диск, видимый почти с ребра, с кольцом пыли перед ним. Астроном эту модель ещё не проверял.",
      "dso-antennae-galaxies": "Две сталкивающиеся галактики там, где их помещает небо, и два их приливных хвоста; насколько каждая часть впереди или позади, — модель по симуляциям столкновения. Астроном эту модель ещё не проверял.",
      "dso-m83": "Построено по опубликованному наклону и структуре: спиральная галактика с перемычкой, видимая почти плашмя, её рукава богаты молодыми звёздами и светящимся водородом. Астроном эту модель ещё не проверял.",
      "dso-ngc-1300": "Построено по опубликованной структуре: длинная перемычка с пылевыми полосами на передних краях и два рукава от её концов, форма которых подогнана к фотографии Hubble. Астроном эту модель ещё не проверял.",
      "dso-centaurus-a": "Построено по опубликованным числам: гигантская эллиптическая галактика, пересечённая искривлённым диском из пыли и молодых звёзд, по модели, подогнанной к снимкам Spitzer; два её джета нарисованы в условных цветах, потому что светят в рентгеновских и радиоволнах, а не в видимом свете. Астроном эту модель ещё не проверял."
    }
  },
