    "vostok-1": {
      "title": "Vostok 1: первый человек в космосе",
      "blurb": "Юрий Гагарин, 12 апреля 1961 года: от Байконура один виток вокруг Земли до поля у Смеловки, по часам миссии, за 108 минут.",
      "chPad": "Гагаринский старт",
      "chAscent": "Подъём",
      "chOrbit": "Один виток",
      "chRetro": "Тормозной импульс",
      "chEntry": "Вход в атмосферу",
      "chEject": "Катапультирование",
      "chLand": "Посадка",
      "ready": "Байконур, площадка 1, 06:07 UTC. Юрий Гагарин, 27 лет, в капсуле на вершине ракеты Р-7.",
      "korolev": "Сергей Королёв по радио: «Предварительная… промежуточная… главная… подъём!»",
      "liftoff": "Старт. Гагарин: «Поехали!»",
      "boosters": "T+119 с: четыре боковых ускорителя выгорают и отпадают.",
      "shroud": "T+156 с: сбрасывается обтекатель над капсулой.",
      "core": "T+300 с: центральная ступень выработана и отпадает; включается последняя ступень.",
      "earth": "Около T+6 мин Гагарин: «Вижу Землю. Видимость хорошая.»",
      "kosberg": "Около T+10 мин последняя ступень выключается. Гагарин: «Косберг сработал!» — по имени конструктора её двигателя.",
      "orbit": "На орбите: 181 на 327 км, наклон 64,95 градуса к экватору, 89,1 минуты на виток. Капсула отделяется от ступени.",
      "retro": "T+1 ч 18 мин, над западным берегом Африки: тормозная ракета работает около 42 секунд. Её время и место опубликованы; её размер здесь подогнан под посадку.",
      "wires": "Приборный отсек должен отделиться через десять секунд после торможения. Его держит пучок проводов; оба кувыркаются вместе в воздух.",
      "entry": "Провода перегорают, и шар поворачивается теплозащитным экраном вперёд. Позже Гагарин сообщал о перегрузке больше 10 g.",
      "eject": "На высоте 7 км люк сбрасывается, и кресло выбрасывает Гагарина. Шар Vostok садился слишком жёстко для человека внутри него.",
      "chutes": "На высоте 2,5 км открывается основной купол капсулы шириной 27 м; собственный купол пилота раскрылся почти сразу. Кресло падает свободно.",
      "landing": "T+1 ч 48 мин: Гагарин приземляется в 26 км к юго-западу от Энгельса Саратовской области, через 108 минут после старта. Источники расходятся в посадке на десять минут.",
      "pathAscent": "подъём — это опубликованные времена событий, соединённые плавными кривыми; высоты и расстояния между ними — наши",
      "pathOrbit": "орбита, торможение и вход в атмосферу — двухтельные дуги, подогнанные под опубликованные времена и поле посадки, а не данные слежения",
      "pathPilot": "спуск под куполом пилота нарисован; ни один источник не даёт расстояния до капсулы",
      "srcWiki": "Википедия, Vostok 1 (времена событий, орбита, цитаты; прочитано 2 ноября 2026)",
      "srcNssdc": "NASA NSSDCA, Vostok 1 (орбита, космический аппарат)"
    },
